#!/usr/bin/env bash
set -euo pipefail

# F-2 challenge composition: the extracted issue driver plus the take adapter
# shared by the three consumers.
#
# This script does NOT regenerate extraction. It reuses
# `proofs/fstar/extraction-challenge-issue-driver/` (regenerated by
# verify-fstar-challenge-issue-driver.sh, which runs first) and checks the
# hand-written composition module against the actual extracted `step`,
# `begin_issue` and the challenge classifier. One nonce key per issue; an
# arbitrary interleaving of issues and of takes by any of the three purposes.

proof_root=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
cd "$proof_root"

for command_name in cargo fstar.exe z3-4.13.3 jq python3; do
  command -v "$command_name" >/dev/null || {
    echo "$command_name is missing; follow README.md" >&2
    exit 1
  }
done

version=$(fstar.exe --version)
printf '%s\n' "$version"
[[ ${version%%$'\n'*} == 'F* 2025.10.06' ]] || {
  echo 'unexpected F* version' >&2
  exit 2
}

[[ -f proofs/fstar/extraction-challenge-issue-driver/Vela_session_policy.Challenge_issue_driver.fst ]] || {
  echo 'run verify-fstar-challenge-issue-driver.sh first' >&2
  exit 1
}

generated=(proofs/fstar/extraction-challenge-issue-driver/Vela_session_policy.Challenge.fst
           proofs/fstar/extraction-challenge-issue-driver/Vela_session_policy.Challenge_issue_driver.fst)
driver_lemmas=(proofs/fstar/challenge-issue-driver-lemmas/Vela_session_policy_challenge_issue_driver_lemmas.fst)
composition=(proofs/fstar/challenge-issue-composition/Vela_session_policy_challenge_issue_composition.fst)
for f in "${generated[@]}" "${driver_lemmas[@]}" "${composition[@]}"; do
  [[ -f $f ]] || { echo "missing $f" >&2; exit 1; }
done

python3 "$proof_root/../../security/formal/check-driver-proof-sources.py" \
  --generated "${generated[@]}" \
  --proof "${driver_lemmas[@]}" "${composition[@]}" \
  --include-dir "$proof_root"

hax_lib_root=$(
  cargo metadata --format-version 1 |
    jq -r '.packages[] | select(.name == "hax-lib") | .manifest_path | sub("/Cargo.toml$"; "")'
)
[[ -n $hax_lib_root && -d $hax_lib_root ]] || {
  echo "could not locate hax-lib proof libraries" >&2
  exit 1
}

fstar_args=(
  --cmi
  --cache_off
  --warn_error -331
  --z3rlimit 16000
  --z3version 4.13.3
  --already_cached '+Prims+FStar+LowStar+C+Spec.Loops+TestLib'
  --include "$hax_lib_root/proof-libs/fstar/core"
  --include "$hax_lib_root/proof-libs/fstar/rust_primitives"
  --include "$hax_lib_root/proofs/fstar/extraction"
  --include proofs/fstar/extraction-challenge-issue-driver
  --include proofs/fstar/challenge-issue-driver-lemmas
  --include proofs/fstar/challenge-issue-composition
  "${generated[@]}" "${driver_lemmas[@]}" "${composition[@]}"
)
printf 'F* challenge-issue-composition argv:'
printf ' %q' "${fstar_args[@]}"
printf '\n'
fstar.exe "${fstar_args[@]}"

echo "challenge composition: every issued key has one purpose and a fresh id; one take consumes it; an accepted take presents its own purpose; wrong-purpose takes spend without accepting"
sha256sum "${generated[@]}" "${driver_lemmas[@]}" "${composition[@]}" \
  src/challenge.rs src/challenge_issue_driver.rs src/challenge_issue_interpreter.rs
